<?php
namespace App\Services\Creative;
use App\Models\{CreativeRequest,CreativeComment,PerformanceEvent,User};
use Illuminate\Support\Facades\DB;
class CreativeProjection {
 public static function stageLabel(CreativeRequest $r):string {return ($r->legacy && $r->stage==='completed' && !$r->completed_at)?'Historically Reported Complete':(($r->legacy && $r->stage==='delivered' && !$r->delivered_at)?'Reported Complete · Awaiting Confirmation':config('creative.stages.'.$r->stage));}

 public function item(CreativeRequest $r,User $actor, ?\Illuminate\Support\Collection $staffNames = null):array {
  $staffNames ??= User::whereKey($r->supportingStaffIds())->pluck('name','id');
  $submissionDeadline=CreativeDeadlines::scoringDue($r);
  $owner=$r->assignee; $requester=$r->requester;$reviewer=$r->reviewer;
  $waiting=in_array($r->stage,['in_review','delivered']);$next=match($r->stage){'in_review'=>'Creative HOD / line manager: inspect work','delivered'=>'Creative HOD / line manager: record client approval','brief_received','backlog'=>'Creative HOD: planning','needs_info'=>$requester?->name??'Requester','completed','archived'=>'No action outstanding',default=>$owner?->name??'Unassigned'};
  $next=$r->is_group?($r->stage==='completed'?'All work packages verified':'Work package owners and reviewers'):$next;
  $project=$r->parent_request_id?$r->parentRequest?->crmProject:$r->crmProject;
  $contact=$project?->owner;
  if(!$contact && User::normalizeDepartmentKey($requester?->department??$r->department)==='client_relations')$contact=$requester;
  $finals=$r->delivered_at&&in_array($r->stage,['delivered','completed','archived'],true)?$r->attachments->filter(fn($a)=>$a->kind==='deliverable'&&$a->iteration>=max(0,$r->iteration-1))->values():collect();
  $final=$finals->first();
  $decisions=$r->updates->whereIn('kind',['needs_info','brief_received','in_review','changes_requested','delivered','completed']);
  $accountability=$decisions->map(fn($event)=>['kind'=>$event->kind,'at'=>$event->created_at->toIso8601String(),'actor'=>$event->author?->name??'Retained staff history','department'=>User::departmentLabel($event->author?->department),'note'=>$event->body,'feedback_type'=>$event->metadata['feedback_type']??null,'iteration'=>(int)($event->metadata['iteration']??0),'review_due_at'=>$event->metadata['review_due_at']??null])->values()->all();
  $raster=$r->attachments->first(fn($a)=>in_array($a->mime,['image/jpeg','image/png','image/webp','video/mp4','video/webm']));
  return ['timeline_provenance'=>app(CreativeTimeline::class)->build($r),'connected_project'=>$project?['id'=>$project->id,'title'=>$project->project_name,'client'=>$project->client_name]:null,'can_link_project'=>CreativeProjectConnection::canUpdate($actor,$r),'submission_deadline'=>$submissionDeadline?\Illuminate\Support\Carbon::parse($submissionDeadline)->toIso8601String():null,'plan_changes'=>$r->planChanges->map(fn($e)=>['actor'=>$e->actor?->name??'Retained staff history','at'=>\Illuminate\Support\Carbon::parse($e->created_at??$e->occurred_at)->toIso8601String(),'reason'=>$e->reason,'before'=>collect($e->before??[])->only(['planned_start','internal_eta','requested_deadline'])->all(),'after'=>collect($e->after??[])->only(['planned_start','internal_eta','requested_deadline'])->all()])->all(),'accountability_events'=>$accountability,'client_relations_contact'=>$contact?['id'=>$contact->id,'name'=>$contact->name]:null,'final_previews'=>$finals->map(fn($a)=>['id'=>$a->id,'url'=>route('portal.creative.attachment',$a),'mime'=>$a->mime,'name'=>$a->original_name])->all(),'final_preview'=>$final?['url'=>route('portal.creative.attachment',$final),'mime'=>$final->mime,'name'=>$final->original_name]:null,'uploads_available'=>!config('creative.upload_scan_required')||(bool)config('creative.upload_scanner'),'is_group'=>$r->is_group,'parent_request_id'=>$r->parent_request_id,'id'=>$r->id,'reference'=>$r->reference,'title'=>$r->title,'brief'=>$r->brief,'brief_html'=>\App\Support\ReportRichText::html($r->brief),'client'=>$r->client,'creative_type'=>$r->creative_type,'department'=>$r->department,'priority'=>$r->priority,'stage'=>$r->stage,'stage_label'=>self::stageLabel($r),'visibility'=>$r->visibility,'legacy'=>$r->legacy,'legacy_received_date_only'=>$r->legacy&&$r->received_at!==null,'revision'=>$r->revision,'iteration'=>$r->iteration,'requester'=>['id'=>$r->requester_id,'name'=>$requester?->name??($r->requester_snapshot['name']??'Not recorded'),'department'=>$r->requester_snapshot['department']??$r->department,'role'=>$r->requester_snapshot['role']??'Not recorded'],'supporting_staff'=>array_map(fn($id)=>['id'=>$id,'name'=>$staffNames[$id]??'Former staff member'],$r->supportingStaffIds()),'assignee'=>['id'=>$r->assignee_id,'name'=>$owner?->name??($r->assignee_snapshot['name']??'Unassigned'),'photo'=>$owner?->profilePhotoUrl()],'reviewer'=>['id'=>$r->reviewer_id,'name'=>$reviewer?->name??'Not recorded'],'next_action'=>$next,'performance_weight'=>$r->task?->weight_approved_at?$r->task->performance_weight:null,'estimated_hours'=>$r->estimated_hours,'quality_score'=>$r->quality_score,'blocker'=>$r->blocker,'blocker_owner'=>$r->blocker_owner,'overdue'=>!in_array($r->stage,['backlog','completed','archived'])&&$r->internal_eta?->isPast()&&!$waiting&&!$r->first_submitted_at,'review_overdue'=>$r->stage==='in_review'&&$r->review_due_at?->isPast(),'on_time_submission'=>$r->first_submitted_at&&$submissionDeadline?$r->first_submitted_at->lte(\Illuminate\Support\Carbon::parse($submissionDeadline)):null,'allowed'=>app(CreativeWorkflow::class)->allowed($r,$actor),'can_replan'=>!$r->is_group&&CreativeAccess::lead($actor)&&!in_array($r->stage,['in_review','delivered','completed','archived'],true),'can_plan'=>CreativeAccess::lead($actor),'can_comment'=>CreativeAccess::view($actor,$r),'can_acknowledge'=>$r->assignee_id===$actor->id&&!$r->acknowledged_at,'preview'=>$raster?['url'=>route('portal.creative.attachment',$raster),'mime'=>$raster->mime,'name'=>$raster->original_name]:null,
   'dates'=>collect(['received_at','acknowledged_at','reported_external_at','source_recorded_at','requested_deadline','planned_start','internal_eta','first_submitted_at','submitted_at','review_due_at','reviewed_at','delivered_at','completed_at'])->mapWithKeys(fn($key)=>[$key=>$r->$key?->toIso8601String()])->all()];
 }
 public function detail(CreativeRequest $r,User $u,int $page=1,int $feedbackPage=1):array {
  $r->load('requester','assignee','reviewer','attachments','task','firstSubmission');$dto=$this->item($r,$u);
  $history=PerformanceEvent::with('actor')->where('entity_type','creative_request')->where('entity_id',$r->id)->orderByDesc('id')->paginate(40,['*'],'history_page',$page);
  $dto['history']=$history->map(fn($e)=>['id'=>$e->id,'action'=>$e->action,'actor'=>$e->actor?->name??'System / retained staff history','at'=>$e->created_at??$e->occurred_at,'reason'=>$e->reason,'before'=>collect($e->before??[])->only(['stage','assignee_id','requested_deadline','internal_eta'])->all(),'after'=>collect($e->after??[])->only(['stage','assignee_id','requested_deadline','internal_eta'])->all()])->all();
  $dto['history_pages']=['current'=>$history->currentPage(),'last'=>$history->lastPage()];
  $feedback=$r->updates()->with('author')->reorder('id','desc')->paginate(40,['*'],'feedback_page',$feedbackPage);
  $dto['updates']=$feedback->getCollection()->map(fn($m)=>['id'=>$m->id,'author'=>$m->author?->name??'Former staff member','at'=>$m->created_at->toIso8601String(),'kind'=>$m->kind,'body'=>$m->body,'url'=>$m->reference_url,'metadata'=>$m->metadata])->all();
  $dto['feedback_pages']=['current'=>$feedback->currentPage(),'last'=>$feedback->lastPage(),'total'=>$feedback->total()];
  $roundUpdates=$r->updates()->with('author')->whereIn('kind',['in_review','changes_requested','delivered','completed'])->orderBy('id')->get();
  $dto['rounds']=$roundUpdates->where('kind','in_review')->map(function($submission)use($roundUpdates){
   $iteration=(int)($submission->metadata['iteration']??0);
   $decisions=$roundUpdates->filter(fn($update)=>(int)($update->metadata['iteration']??-1)===$iteration&&$update->id>$submission->id);
   $correction=$decisions->firstWhere('kind','changes_requested');$approval=$decisions->firstWhere('kind','delivered');
   return ['iteration'=>$iteration,'submitted_at'=>$submission->created_at->toIso8601String(),'submitted_by'=>$submission->author?->name??'Former staff member','feedback_due_at'=>$submission->metadata['review_due_at']??null,'corrections_at'=>$correction?->created_at?->toIso8601String(),'corrections_by'=>$correction?->author?->name,'feedback'=>$correction?->body,'feedback_type'=>$correction?->metadata['feedback_type']??null,'approved_at'=>$approval?->created_at?->toIso8601String(),'approved_by'=>$approval?->author?->name];
  })->values()->all();
  $dto['attachments']=$r->attachments->map(fn($a)=>['id'=>$a->id,'name'=>$a->original_name,'kind'=>$a->kind,'mime'=>$a->mime,'iteration'=>$a->iteration,'at'=>$a->created_at->toIso8601String(),'url'=>route('portal.creative.attachment',$a),'download'=>route('portal.creative.attachment',[$a,'download'=>1])])->all();
  $dto['parts']=$r->parts()->visibleTo($u)->get(['id','reference','title','stage','assignee_id'])->map(fn($p)=>['id'=>$p->id,'reference'=>$p->reference,'title'=>$p->title,'stage'=>config('creative.stages.'.$p->stage)])->all();$dto['can_split']=CreativeAccess::lead($u)&&!$r->task_id&&!$r->assignee_id&&!$r->is_group&&!$r->parent_request_id&&in_array($r->stage,['backlog','brief_received','needs_info']);
  $dto['connected_html']='';
  if(($projectId=$dto['connected_project']['id']??null) && ($project=\App\Models\CrmPipelineProject::find($projectId))) $dto['connected_html']=view('portal.project-journey.accountability',['accountability'=>app(\App\Services\ConnectedProjectSummary::class)->build($project,$u)])->render();
  $dto['sources']=DB::table('creative_sources')->where('creative_request_id',$r->id)->get(['source_type','source_id'])->all();
  $weeklyIds=collect($dto['sources'])->where('source_type','weekly')->pluck('source_id');
  $dto['weekly_reports_html']=\App\Models\WeeklyConsolidatedItem::whereIn('id',$weeklyIds)->orderByDesc('week_start')->get()->map(fn($item)=>view('portal.partials.creative-weekly-entry-actions',['item'=>$item,'editorActor'=>$u])->render())->implode('');
  $dto['legacy_comments']=$r->task_id?CreativeComment::with('user')->where('task_id',$r->task_id)->latest()->limit(50)->get()->map(fn($c)=>['author'=>$c->user?->name??'Former staff member','at'=>$c->created_at->toIso8601String(),'body'=>$c->comment??$c->message??$c->body??'Historical proofing comment','attachment'=>$c->attachment_path?true:false])->all():[];
  $dto['alerts']=\App\Models\PerformanceOutbox::where('url',route('portal.creative',['request'=>$r->id]))->with('user')->latest('id')->limit(30)->get()->map(fn($n)=>['recipient'=>$n->user?->name??'Former staff member','title'=>$n->title,'queued_at'=>$n->created_at,'in_app_at'=>$n->dashboard_at,'email_at'=>$n->emailed_at,'attempts'=>$n->attempts,'status'=>$n->last_error?'Retry needed':($n->dashboard_at?'In-app delivered':'Queued')])->all();
  return $dto;
 }
}
